// 1. Fetch extractor payload
const extractorNode = $('Information Extractor').first()?.json;
const extractorData = extractorNode?.output || extractorNode || {};

// 2. Fetch the existing booking record from Insert Booking (Confirmed) or incoming data
const existingBooking = $('Insert Booking (Confirmed)').first()?.json || $json || {};

// 3. Dynamically set start and end dates from the extractor
const startIso = extractorData.appointment_start || '2026-09-25T14:00:00+05:30';
const startDate = new Date(startIso);

let endDate;
if (extractorData.appointment_end) {
  endDate = new Date(extractorData.appointment_end);
} else {
  endDate = new Date(startDate.getTime() + (30 * 60 * 1000));
}

// 4. Resolve the calendar event ID dynamically
const eventId = existingBooking.calendar_event_id 
  || existingBooking.google_event_id 
  || existingBooking.event_id 
  || 'ajalbe1is5670oi69nh6lms37o';

return [
  {
    json: {
      existing_event_id: eventId,
      booking_id: existingBooking.id || 61,
      patient_name: extractorData.patient_name || existingBooking.patient_name || 'John Doe',
      patient_phone: extractorData.patient_phone || existingBooking.patient_phone || '+15551234567',
      doctor_name: extractorData.doctor_name || existingBooking.doctor_name || 'Dr. Smith',
      slot_start: startDate.toISOString(),
      slot_end: endDate.toISOString()
    }
  }
];

