    },
    "doctor_name": {
      "type": "string",
      "description": "Requested practitioner name if specified (e.g., Dr. Smith, Dr. Rampuria). Otherwise null."
    },
    "appointment_start": {
      "type": "string",
      "description": "Target appointment start timestamp in ISO 8601 format (YYYY-MM-DDTHH:mm:ss+05:30). Resolved from current reference time."
    },
    "appointment_end": {
      "type": "string",
