// Bulletproof VAPI & Telephony Call Ingest Normalizer
const items = $input.all();
if (!items.length) return [];

const item = items[0].json;
const raw = item.body || item;

// 1. Safe extraction of VAPI transcript
let transcript = 
  raw.message?.artifact?.transcript ||
  raw.message?.transcript ||
  raw.artifact?.transcript ||
  raw.transcript ||
  raw.message?.text ||
  raw.message?.call?.transcript ||
  raw.message ||
  raw.chatInput ||
  raw.text ||
  '';

// Force transcript to be a clean string safely
if (typeof transcript !== 'string') {
  try {
    transcript = JSON.stringify(transcript) || '';
  } catch (e) {
    transcript = String(transcript || '');
  }
}
transcript = transcript.trim();

// 2. Extract Caller / Patient Phone Number
let incomingPhone = 
  raw.message?.call?.customer?.number ||
  raw.call?.customer?.number ||
  raw.customer?.number ||
  raw.message?.customer?.number ||
  raw.patient_phone ||
  raw.phone ||
  raw.caller_id ||
  raw.From ||
  null;

if (incomingPhone && typeof incomingPhone === 'string') {
  incomingPhone = incomingPhone.trim();
}

return [{
  json: {
    transcript: transcript,
    incoming_phone: incomingPhone,
    received_at: new Date().toISOString(),
    vapi_call_id: raw.message?.call?.id || raw.call?.id || null
  }
}];

