let patientName = 'Valued Patient';
let patientPhone = 'Unknown Phone';

try {
  // Matched to your exact trigger node title
  const vapiData = $('Vapi Post-Call Ingest').first().json;

  // 1. Extract Phone Number
  patientPhone = vapiData.message?.call?.customer?.number 
              || vapiData.customer?.number 
              || patientPhone;

  // 2. Extract Patient Name from Transcript
  const transcript = vapiData.message?.artifact?.transcript || '';
  const match = transcript.match(/for\s+([A-Za-z\s]+?)(?:[.,]|$)/i);
  if (match && match[1]) {
    patientName = match[1].trim();
  }
} catch (error) {
  // Fallback defaults if node context is unlinked during isolated tests
}

return [{
  json: {
    patient_name: patientName,
    patient_phone: patientPhone
  }
}];
